import{c as d,Z as i,Q as r,j as e,m as a,g as s,n as l,o as p,av as o}from"./chunks/framework.rWdQudnF.js";const S=JSON.parse('{"title":"错题记录","description":"","frontmatter":{"title":"错题记录"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/错题记录.md","filePath":"综合知识/系统基础/操作系统/错题记录.md","lastUpdated":null}'),c={name:"综合知识/系统基础/操作系统/错题记录.md"},g={class:"callout callout-note"},u={class:"callout-body"};function h(m,t,b,y,_,v){const n=i("font");return r(),e("div",null,[t[7]||(t[7]=a('<hr><p><strong>[Q54] 信号量值含义</strong></p><p>若信号量S的初始值为3，当前值为-1，则表示（ ）个进程正在等待该资源。</p><ul><li>A. 0</li><li>B. 1</li><li>C. 2</li><li>D. 3</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：S&lt;0时，|S|=等待进程数。|-1|=1个进程在等待。</p><p>这道题考的是 <strong>信号量值的含义</strong>，规则很简单：</p><p><strong>信号量 S 的含义：</strong></p><ul><li>S ≥ 0 → S 表示<strong>可用资源数</strong></li><li>S &lt; 0 → |S| 表示<strong>等待该资源的进程数</strong></li></ul><hr><p><strong>逐步推演：</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>S 值变化</th><th>说明</th></tr></thead><tbody><tr><td>初始</td><td>S = 3</td><td>3 个资源可用</td></tr><tr><td>进程 A 执行 P 操作</td><td>S = 2</td><td>占用 1 个，剩 2 个可用</td></tr><tr><td>进程 B 执行 P 操作</td><td>S = 1</td><td>占用 2 个，剩 1 个可用</td></tr><tr><td>进程 C 执行 P 操作</td><td>S = 0</td><td>占用 3 个，<strong>资源刚好用完</strong></td></tr><tr><td>进程 D 执行 P 操作</td><td><strong>S = -1</strong></td><td>资源已用完，<strong>D 进入等待队列</strong></td></tr></tbody></table><p>当 S = -1：</p><ul><li>绝对值 |-1| = <strong>1</strong> → 有 <strong>1 个进程</strong>在等待（进程 D）</li><li>同时意味着 3 个资源全被占用</li></ul><p><strong>所以选 B（1 个进程等待）</strong></p></div></details><hr><p><strong>[Q66] 前趋图PV规则</strong></p><p>在使用信号量实现前驱关系时，以下哪个步骤是正确的（ ）。</p><ul><li>A. 设置的信号量数量等于进程数</li><li>B. 所有信号量的初始值设为1</li><li>C. 进程执行前进行V操作，执行后进行P操作</li><li>D. 信号量数量等于有向边数量，初始值为0</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：信号量数=有向边数，初值全0，前驱执行后V，后继执行前P。</p></div></details><hr><p><strong>[Q64] 死锁条件</strong></p><p>在操作系统中，以下哪个条件不是产生死锁的必要条件（ ）。</p><ul><li>A. 资源共享</li><li>B. 保持和等待</li><li>C. 不可剥夺</li><li>D. 环路等待</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：死锁四条件：互斥、占有等待、不可剥夺、环路等待。&quot;资源共享&quot;不是。</p><p>死锁四个必要条件</p><table tabindex="0"><thead><tr><th>条件</th><th>含义</th></tr></thead><tbody><tr><td><strong>互斥</strong></td><td>资源一次只能给一个进程用</td></tr><tr><td><strong>保持和等待</strong></td><td>进程占着资源不放，还等别的资源</td></tr><tr><td><strong>不可剥夺</strong></td><td>资源不能被强行抢走</td></tr><tr><td><strong>环路等待</strong></td><td>进程间形成循环等待链</td></tr><tr><td>选 A 的原因</td><td></td></tr></tbody></table><p><strong>A. 资源共享</strong> ❌ — 不是必要条件</p><ul><li>死锁需要的是<strong>互斥（资源不能共享）</strong>，而不是共享</li><li>如果一个资源可以共享（比如只读文件），多个进程同时用不会死锁</li><li>所以「资源共享」恰恰是<strong>避免</strong>死锁的方向，不是产生死锁的条件</li></ul></div></details><hr><p><strong>[Q9] 并发+死锁</strong></p><p>若一个单处理器的计算机系统中同时存在3个并发进程，则同一时刻允许占用处理器的进程数（ ）；如果这3个进程都要求使用2个互斥资源R，那么系统不产生死锁的最少的R资源数为（ ）个。</p><ul><li>A. 至少为1个</li><li>B. 至少为3个</li><li>C. 最多为1个</li><li>D. 最多为3个</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C（最多1个）</p><p>解析：单处理器同一时刻最多1个进程占用CPU。死锁最小资源=3×(2-1)+1=4，选项未给出第二问。</p></div></details><hr><p><strong>[Q72] 调度</strong></p><p>在操作系统中，哪种调度不涉及进程在内存和外存之间的交换（ ）。</p><ul><li>A. 高级调度</li><li>B. 中级调度</li><li>C. 低级调度</li><li>D. 实时调度</li></ul>',24)),s("details",g,[t[6]||(t[6]=s("summary",{class:"callout-title"},[s("span",{class:"callout-icon"},"📝"),l("答案与解析")],-1)),s("div",u,[t[2]||(t[2]=a('<p>答案：C</p><p>解析：低级调度=CPU分配，不涉及内存-外存交换；中级调度才涉及。</p><p>这道题选 <strong>C（低级调度）</strong> ✅。<code>实时调度</code> 不是三级调度中的概念，是两个不同的维度。</p><hr><p>三级调度回顾</p><table tabindex="0"><thead><tr><th>调度级别</th><th>别名</th><th>做什么</th><th style="text-align:center;">是否涉及内外存交换</th></tr></thead><tbody><tr><td><strong>高级调度</strong></td><td>作业调度</td><td>决定哪个后备作业调入内存成为就绪进程</td><td style="text-align:center;">✅ 是</td></tr><tr><td><strong>中级调度</strong></td><td>对换调度</td><td>决定交换区中哪个进程换入内存</td><td style="text-align:center;">✅ 是</td></tr><tr><td><strong>低级调度</strong></td><td>进程调度</td><td>决定内存中哪个就绪进程拿到 CPU</td><td style="text-align:center;">❌ <strong>否</strong></td></tr></tbody></table><p>低级调度只看<strong>谁上 CPU</strong>，进程已经在内存里了，不涉及搬进搬出。所以选 C。</p><hr>',8)),p(n,{color:"#f79646"},{default:o(()=>[...t[0]||(t[0]=[l('实时调度不是"第四个级别"',-1)])]),_:1}),t[3]||(t[3]=a(`<p><strong>实时调度</strong>是调度<strong>算法/策略的分类</strong>，而不是一个独立的调度级别。</p><p>三级调度是按<strong>发生的位置和时机</strong>分的（作业层→交换层→CPU 层），而实时调度是按<strong>调度目标</strong>分的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调度策略分类：  </span></span>
<span class="line"><span>├── 先来先服务（FCFS）  </span></span>
<span class="line"><span>├── 时间片轮转（RR）  </span></span>
<span class="line"><span>├── 优先级调度  </span></span>
<span class="line"><span>├── 多级反馈队列  </span></span>
<span class="line"><span>└── 实时调度（保证任务在截止时间前完成）  </span></span>
<span class="line"><span>        ├── 速率单调调度（RMS）— 静态优先级  </span></span>
<span class="line"><span>        └── 最早截止时间优先（EDF）— 动态优先级</span></span></code></pre></div><p><strong>实时调度</strong>关注的是<strong>能不能按时完成</strong>，它在三级调度中属于<strong>低级调度</strong>这个层面 — 决定当前哪个进程上 CPU，只是选谁的标准变了（看截止时间而非优先级/时间片）。</p><hr>`,5)),p(n,{color:"#4bacc6"},{default:o(()=>[...t[1]||(t[1]=[l("一句话区分",-1)])]),_:1}),t[4]||(t[4]=s("p",null,[l("高级/中级/低级 = "),s("strong",null,"在哪个阶段做调度"),l(" 实时调度 = "),s("strong",null,"用什么标准来做调度"),l("（按时完成优先）")],-1)),t[5]||(t[5]=s("p",null,[l("所以题目中的 D 选项其实是一个分类错误 — 它和 A/B/C 不在同一个维度上。但标准答案还是 "),s("strong",null,"C（低级调度）"),l("，因为它是唯一明确不涉及内外存交换的")],-1))])]),t[8]||(t[8]=a(`<hr><blockquote><p>⭐ <strong>经典题目</strong> — 链式存储+成组分解字节定位易错（块号从0计数，整除为边界）</p></blockquote><p><strong>[Q20] 链式存储+成组分解</strong></p><p>某文件系统采用链式存储管理方式并应用记录的成组与分解技术，且磁盘块的大小为 4096 字节。若文件 license.doc 由 7 个逻辑记录组成，每个逻辑记录的大小为 2048字节，并依次存放在 58、89、96 和 101 号磁盘块上，那么要存取文件的第 12288 逻辑字节处的信息，应访问（ ）号磁盘块。</p><ul><li>A. 58</li><li>B. 89</li><li>C. 96</li><li>D. 101</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：每块存2个记录(4096/2048=2)。12288/4096=3，第3块(从0计)→101号块。</p><p><strong>已知条件：</strong></p><ul><li>磁盘块大小 = <strong>4096 字节</strong></li><li>每个逻辑记录 = <strong>2048 字节</strong></li><li>所以 <strong>每块存 2 个记录</strong>（4096 ÷ 2048 = 2）</li><li>文件存于 4 个盘块（链式）：<code>58 → 89 → 96 → 101</code></li></ul><p><strong>目标：访问逻辑字节 12288</strong></p><p><strong>第一步：确定在第几个磁盘块</strong></p><p>每块 4096 字节，用逻辑字节数除以块大小：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12288 ÷ 4096 = 3 （整除，无余数）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>块号（从0计）</th><th>字节范围</th><th>物理块</th></tr></thead><tbody><tr><td>第0块</td><td>0 ~ 4095</td><td>58</td></tr><tr><td>第1块</td><td>4096 ~ 8191</td><td>89</td></tr><tr><td>第2块</td><td>8192 ~ 12287</td><td>96</td></tr><tr><td><strong>第3块</strong></td><td><strong>12288 ~ 16383</strong></td><td><strong>101</strong></td></tr></tbody></table><p>12288 正好是第 3 块的起始位置（第0块是 0~4095 别忘了）。</p><p><strong>第二步：链式存储 → 逐块跟踪</strong></p><p>链式存储下物理块不连续，靠指针串联：</p><ul><li>文件第1块 → 58</li><li>第2块 → 89（58指向89）</li><li>第3块 → 96（89指向96）</li><li><strong>第4块 → 101</strong>（96指向101）</li></ul><p>所以第 3 块（从0计）对应物理块 <strong>101</strong>。</p><p>简单说：12288 ÷ 4096 = 3 → 第 3 块（0-indexed）→ 链式第四个节点 → <strong>101</strong></p></div></details><hr><p><strong>[Q57] 连续结构</strong></p><p>（ ）文件组织方式支持快速随机访问但易产生碎片。</p><ul><li>A. 连续结构</li><li>B. 链接结构</li><li>C. 索引结构</li><li>D. 哈希结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：连续结构=文件块连续存放→随机访问快；但增删文件易产生外碎片。</p></div></details><hr><p><strong>[Q59] 文件属性</strong></p><p>在文件管理系统中，以下哪个文件属性表示该文件是一个系统文件（ ）。</p><ul><li>A. R</li><li>B. A</li><li>C. S</li><li>D. H</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：R=只读(Read-only)，A=归档(Archive)，S=系统(System)，H=隐藏(Hidden)。</p></div></details><hr><p><strong>[Q85] 硬链接</strong></p><p>关于文件的硬链接，下列描述正确的是（ ）。</p><ul><li>A. 创建新的文件实体</li><li>B. 两个文件目录项指向同一个索引节点</li><li>C. 建立文件路径的映射关系</li><li>D. 必须位于同一个文件系统</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：硬链接=多个目录项指向同一inode，不创建新实体，共享同一索引节点。</p><p>D 的描述也是对的，不过更多是约束条件，选择B描述更准确一些。</p></div></details><hr><blockquote><p>⭐ <strong>经典题目</strong> — 索引地址计算核心题（直接/一级间接/二级间接的边界定位）</p></blockquote><p>设文件索引节点有 8 个地址项（每项 4 字节）：5 个直接地址索引，2 个一级间接索引，1 个二级间接索引。磁盘索引块和数据块大小均为 1KB。</p><p><strong>Q1</strong>：访问逻辑块号 5 和 518，分别采用什么索引？</p><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p></p><p>答案：<strong>一级间接地址索引和二级间接地址索引</strong></p><p>解析：</p><ul><li>直接索引：0~4（5 个）</li><li>一级间接索引：每节点 1KB/4B=256 个块，2 个节点覆盖 5~516</li><li>二级间接索引：517 以上</li><li>逻辑块 5 在 5~516 范围 → 一级间接；518 &gt; 516 → 二级间接</li></ul><hr><p>答案：逻辑块 5 → <strong>一级间接地址索引</strong>，逻辑块 518 → <strong>二级间接地址索引</strong></p><p>这题是索引结构的经典计算，一步步拆：</p><hr><p>已知条件</p><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>地址项总数</td><td>8 个（iaddr[0]~iaddr[7]）</td></tr><tr><td>直接索引</td><td>5 个（iaddr[0]~iaddr[4]）</td></tr><tr><td>一级间接索引</td><td>2 个（iaddr[5]~iaddr[6]）</td></tr><tr><td>二级间接索引</td><td>1 个（iaddr[7]）</td></tr><tr><td>磁盘块大小</td><td>1KB = 1024 字节</td></tr><tr><td>每个地址占</td><td>4 字节</td></tr></tbody></table><hr><p>第一步：每个间接节点能管多少块？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个磁盘块可存地址数 = 1024 ÷ 4 = 256 个</span></span></code></pre></div><ul><li><strong>直接索引</strong>：1 个节点管 1 块</li><li><strong>一级间接</strong>：1 个节点管 <strong>256 块</strong></li><li><strong>二级间接</strong>：1 个节点管 256 × 256 = <strong>65536 块</strong></li></ul><hr><p>第二步：画逻辑块号区间图</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地址项        类型          覆盖逻辑块号范围       块数  </span></span>
<span class="line"><span>─────────────────────────────────────────────────────────  </span></span>
<span class="line"><span>iaddr[0]  ─ 直接            0                       1  </span></span>
<span class="line"><span>iaddr[1]  ─ 直接            1                       1  </span></span>
<span class="line"><span>iaddr[2]  ─ 直接            2                       1  </span></span>
<span class="line"><span>iaddr[3]  ─ 直接            3                       1  </span></span>
<span class="line"><span>iaddr[4]  ─ 直接            4                       1  </span></span>
<span class="line"><span>                              ────────  </span></span>
<span class="line"><span>                              0 ~ 4                 5 块  </span></span>
<span class="line"><span>─────────────────────────────────────────────────────────  </span></span>
<span class="line"><span>iaddr[5]  ─ 一级间接         5 ~ 260               256 块  </span></span>
<span class="line"><span>iaddr[6]  ─ 一级间接         261 ~ 516              256 块  </span></span>
<span class="line"><span>                              ────────  </span></span>
<span class="line"><span>                              5 ~ 516              512 块  </span></span>
<span class="line"><span>─────────────────────────────────────────────────────────  </span></span>
<span class="line"><span>iaddr[7]  ─ 二级间接         517 起                 65536 块</span></span></code></pre></div><hr><p>第三步：定位</p><table tabindex="0"><thead><tr><th>逻辑块号</th><th>落在区间</th><th>索引类型</th></tr></thead><tbody><tr><td><strong>5</strong></td><td>5~260（iaddr[5]）</td><td><strong>一级间接索引</strong></td></tr><tr><td><strong>518</strong></td><td>517 以上（iaddr[7]）</td><td><strong>二级间接索引</strong></td></tr></tbody></table><p>答案：逻辑块 5 → <strong>一级间接地址索引</strong>，逻辑块 518 → <strong>二级间接地址索引</strong></p><p>注意边界：逻辑块 4 还是直接索引（iaddr[4]），逻辑块 5 就进入了一级间接</p></div></details><p><strong>Q2</strong>：单个文件最大长度是多少 KB？</p><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p></p><p>答案：<strong>66053 KB</strong></p><p>解析：5（直接） + 256×2（一级间接，2个节点各256块） + 256×256（二级间接，256个一级节点各256块）= 5 + 512 + 65536 = 66053 KB</p></div></details><hr><p><strong>[Q18] 索引节点-地址计算</strong></p><p>假设文件系统采用索引节点管理，且索引节点有8个地址项iaddr[0]～iaddr[7]，每个地址项大小为4字节，iaddr[0]～iaddr[4]采用直接地址索引，iaddr[5]和iaddr[6]采用一级间接地址索引，iaddr[7]采用二级间接地址索引。假设磁盘索引块和磁盘数据块大小均为1KB字节。若用户访问文件File1中逻辑块号为5和261的信息，则对应的物理块号分别为（ ）。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260515171817.png" alt="image.png"></p><ul><li>A. 89和90</li><li>B. 89和136</li><li>C. 58和187</li><li>D. 90和136</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：直接索引0~4(5块)覆盖逻辑块0~4；一级间接=256块/节点。逻辑块5→iaddr[5]一级间接第0项→58；逻辑块261→261-5=256→iaddr[6]一级间接第0项→187。</p></div></details><hr><p><strong>[Q19] 索引节点-间接索引</strong></p><p>同上题条件。101号物理块存放的是（ ）。</p><ul><li>A. File1的信息</li><li>B. 直接地址索引表</li><li>C. 一级地址索引表</li><li>D. 二级地址索引表</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：iaddr[7]二级间接→先读一级索引块→再读二级索引块。101号块是二级地址索引表。</p></div></details>`,39))])}const A=d(c,[["render",h]]);export{S as __pageData,A as default};
